import * as tags from './index'
import assert from 'assert'

// Track deprecation warnings
const deprecationWarnings = []
const originalConsoleWarn = console.warn

describe('tags', () => {
  let context
  let calls

  before(() => {
    console.warn = (message) => {
      deprecationWarnings.push(message)
    }
  })

  after(() => {
    console.warn = originalConsoleWarn
  })

  beforeEach(() => {
    calls = {
      getState: [],
      getSequence: [],
      getSequences: [],
    }

    deprecationWarnings.length = 0

    // Create realistic context for testing
    context = {
      module: {
        name: 'testModule',
      },
      execution: {
        name: 'testModule.someAction',
      },
      controller: {
        getState(path) {
          calls.getState.push(path)

          if (path === 'some.path') return 'state_result'
          if (path === 'testModule.foo') return 'module_state_result'
          if (path === 'testModule.some.path') return 'module_deprecated_result'

          return `state_${path}`
        },
        getSequence(path) {
          calls.getSequence.push(path)

          if (path === 'some.path') return 'sequence_result'
          if (path === 'testModule.some.path') return 'module_sequence_result'

          return null
        },
        getSequences(path) {
          calls.getSequences.push(path)

          if (path === 'some.path') return 'sequences_result'
          if (path === 'testModule.some.path') return 'module_sequences_result'

          return `sequences_${path}_result`
        },
      },
      props: {
        foo: 'bar',
        nested: {
          value: 'nestedValue',
        },
      },
    }
  })

  describe('Tag functionality', () => {
    it('string tag should return the path string', () => {
      const tag = tags.string`some.path`
      assert.strictEqual(tag.getValue(context), 'some.path')
    })

    it('path tag should return the path string', () => {
      const tag = tags.path`some.path`
      assert.strictEqual(tag.getValue(context), 'some.path')
    })

    it('state tag should get state from controller', () => {
      const tag = tags.state`some.path`

      assert.strictEqual(tag.getValue(context), 'state_result')
      assert.deepEqual(calls.getState, ['some.path'])
    })

    it('sequences tag should get sequence from controller if available', () => {
      const tag = tags.sequences`some.path`

      assert.strictEqual(tag.getValue(context), 'sequence_result')
      assert.deepEqual(calls.getSequence, ['some.path'])
    })

    it('sequences tag should get sequences from controller if sequence not available', () => {
      // Modify getSequence to test fallback behavior
      const originalGetSequence = context.controller.getSequence
      context.controller.getSequence = (path) => {
        calls.getSequence.push(path)
        return null // Return null to test the fallback
      }

      const tag = tags.sequences`some.path`

      assert.strictEqual(tag.getValue(context), 'sequences_result')
      assert.deepEqual(calls.getSequence, ['some.path'])
      assert.deepEqual(calls.getSequences, ['some.path'])

      // Restore the original function
      context.controller.getSequence = originalGetSequence
    })

    it('moduleState tag should get state with root path', () => {
      const tag = tags.moduleState`foo`

      assert.strictEqual(tag.getValue(context), 'module_state_result')
      assert.deepEqual(calls.getState, ['testModule.foo'])
    })

    it('moduleSequences tag should get sequence with root path if available', () => {
      const tag = tags.moduleSequences`some.path`

      assert.strictEqual(tag.getValue(context), 'module_sequence_result')
      assert.deepEqual(calls.getSequence, ['testModule.some.path'])
    })

    it('moduleSequences tag should get sequences with root path if sequence not available', () => {
      // Modify getSequence to test fallback behavior
      const originalGetSequence = context.controller.getSequence
      context.controller.getSequence = (path) => {
        calls.getSequence.push(path)
        return null // Return null to test the fallback
      }

      const tag = tags.moduleSequences`some.path`

      assert.strictEqual(tag.getValue(context), 'module_sequences_result')
      assert.deepEqual(calls.getSequence, ['testModule.some.path'])
      assert.deepEqual(calls.getSequences, ['testModule.some.path'])

      // Restore the original function
      context.controller.getSequence = originalGetSequence
    })

    it('props tag should extract simple value from props', () => {
      const tag = tags.props`foo`
      assert.strictEqual(tag.getValue(context), 'bar')
    })

    it('props tag should extract nested value from props', () => {
      const tag = tags.props`nested.value`
      assert.strictEqual(tag.getValue(context), 'nestedValue')
    })
  })

  describe('Deprecated tags', () => {
    it('signal tag should get sequence from controller and show deprecation warning', () => {
      const tag = tags.signal`some.path`

      assert.strictEqual(tag.getValue(context), 'sequence_result')
      assert.deepEqual(calls.getSequence, ['some.path'])
      assert.ok(
        deprecationWarnings.some(
          (msg) =>
            msg.includes('tags.signal') &&
            msg.includes('use the "sequences" tag instead')
        )
      )
    })

    it('signals tag should get sequences from controller and show deprecation warning', () => {
      const tag = tags.signals`some.path`

      assert.strictEqual(tag.getValue(context), 'sequences_result')
      assert.deepEqual(calls.getSequences, ['some.path'])
      assert.ok(
        deprecationWarnings.some(
          (msg) =>
            msg.includes('tags.signals') &&
            msg.includes('use the "sequences" tag instead')
        )
      )
    })

    it('module tag should get state with root path and show deprecation warning', () => {
      const tag = tags.module`some.path`

      assert.strictEqual(tag.getValue(context), 'module_deprecated_result')
      assert.deepEqual(calls.getState, ['testModule.some.path'])
      assert.ok(
        deprecationWarnings.some(
          (msg) =>
            msg.includes('tags.module') &&
            msg.includes('use the "moduleState" tag instead')
        )
      )
    })
  })

  // Just test tag exports - detailed proxy transformation tests are in proxy-transform.test.js
  describe('Tag exports for proxies', () => {
    it('should export all necessary tags for proxy transformation', () => {
      assert.ok(tags.state, 'state tag should be exported')
      assert.ok(tags.sequences, 'sequences tag should be exported')
      assert.ok(tags.props, 'props tag should be exported')
      assert.ok(tags.moduleState, 'moduleState tag should be exported')
      assert.ok(tags.moduleSequences, 'moduleSequences tag should be exported')
      assert.ok(tags.string, 'string tag should be exported')
    })
  })
})
